import { Component, OnInit } from '@angular/core';
import { FormGroup } from '@angular/forms';
import { ActivatedRoute, Router } from '@angular/router';
import { cloneDeep } from '@apollo/client/utilities';
import { AlertService } from 'src/app/services/alert.service';
import { EmisService } from 'src/app/services/emis/emis.service';
import { UserSessionService } from 'src/app/services/usersession.service';
@Component({
  selector: 'app-ie-stdmapping-therapist',
  templateUrl: './ie-stdmapping-therapist.page.html',
  styleUrls: ['./ie-stdmapping-therapist.page.scss'],
})
export class IeStdmappingTherapistPage implements OnInit {

  searchText: any = '';
  blkStdList: any = [];
  paramdata: any = '';
  stdTypeList: any = [];
  noParents: any = '';
  docUpload: any = '';
  fileType: any = '';
  doc_file: any = '';
  userName: any = '';
  form: FormGroup;
  summCount: any = {};

  constructor(private router: Router, private alertService: AlertService,
    private emisService: EmisService,
    private userSessionService: UserSessionService,
    private route: ActivatedRoute) { }

  ngOnInit() {
    this.form = new FormGroup({});
    this.stdTypeList = [
      { label: "Adaptation in the School & Classroom Required", id: 1 },
      { label: "Home-Based", id: 2 },
      { label: "School + Center", id: 3 },
      { label: "Home Based + IE", id: 4 },
      { label: "No Therapeutic Intervention", id: 5 },
    ];
    // this.route.queryParams.subscribe((res: any) => {
    //   if (res) {
    //   }
    // })
  }


  ionViewDidEnter() {
    this.userName = this.userSessionService.emis_username();
    this.getIeCenterStdList();
  }

  goToBack() {
    this.router.navigate(["/tabs/cwsn/dashboard"])
  }

  getIeCenterStdList() {
    let obj = {
      userId: this.userSessionService.emis_username()
    };
    this.emisService.IECntrBlkStdList(obj).subscribe(res => {
      if (res.dataStatus) {
        this.blkStdList = [];
        res.result.forEach(obj1 => {
          if (obj1.stdType) {
            obj1.stdType =this.stdTypeList.find(obj3 => { return obj1.stdType == obj3.id  });
          }
          this.blkStdList.push(obj1);
        });;
        this.calcSummary();
      } else {
        this.blkStdList = [];
        this.alertService.warning(res.message);
      };
    })
  }

  finalSubmit() {
    // if (form.valid) {
      let arr = [];
      for (let i = 0; i < this.blkStdList.length; i++) {
        let stdType: any = '';
        if (this.blkStdList[i].stdType) {
          stdType = this.blkStdList[i].stdType.id;
          arr.push({
            "UserId": this.blkStdList[i].userId,
            "SchoolId": this.blkStdList[i].schId,
            "addBy": this.userSessionService.emis_username(),
            "blkId": this.userSessionService.BlkdId(),
            "stdType": stdType,
            "isactive": stdType == 0 ? stdType : 1,
            "IndexId": this.blkStdList[i].IndexId
          });
        }
      }
      let obj = {
        "records": arr
      }
      if (arr.length > 0) {
        this.emisService.IECntrTherptStdMap(obj).subscribe(res => {
          if (res.dataStatus) {
            for (let i = 0; i < res.resData.length; i++) {
              let idx = this.blkStdList.findIndex(obj => { return obj.userId == res.resData[i].user_id });
              if (idx != -1) {
                this.blkStdList[idx].IndexId = res.resData[i].IndexId;
              }
            }
            this.alertService.success(res.message);
            this.calcSummary();
          } else {
            this.alertService.warning(res.message);
          };
        })
      } else {
        this.alertService.warning('Please mark attendance for students');
      }
    // } else {
    //   this.alertService.warning('Form is invalid');
    // }
  }

  assessSort(array, field) {
    array.sort(function (x, y) {
      if (x[field] < y[field])
        return -1;
      if (x[field] > y[field])
        return 1;
      return 1;
    });
    return array;
  }

  calcSummary() {
    let modification = 0, homeBased = 0, schoolCenter = 0, therapeuticIntervention = 0,homeCenter=0;
    this.blkStdList.forEach(obj => {
      if (obj.stdType) {
        let sId= obj.stdType.id;
        if (sId==1) {
          modification = modification+1;
        }else if(sId==2) {
          homeBased = homeBased+1;
        }else if(sId==3) {
          schoolCenter = schoolCenter+1;
        }else if(sId==4) {
          homeCenter = homeCenter+1;
        }else if(sId==5) {
          therapeuticIntervention = therapeuticIntervention+1;
        }
      }
    });
    this.summCount = {modification,homeBased,schoolCenter,therapeuticIntervention,homeCenter};
    this.blkStdList.sort((a, b) => parseFloat(a.IndexId ? a.IndexId : 0) - parseFloat(b.IndexId ? b.IndexId : 0));
  }
}